<?php
class AiTools {
    private $store;
    public function __construct($store){$this->store=$store;}
    public static function definitions($grant){
        $object=['type'=>'object','properties'=>new stdClass()];
        $defs=[['name'=>'project_context','description'=>'Read authorized project context and available data sources.','inputSchema'=>$object],['name'=>'workflow_counts','description'=>'Exact counts of inventory and production work queues.','inputSchema'=>$object],['name'=>'read_data','description'=>'Read paginated products, sales, calendar or uploaded analytical datasets. Continue next_offset to get all records.','inputSchema'=>['type'=>'object','properties'=>['source'=>['type'=>'string'],'offset'=>['type'=>'integer','minimum'=>0],'limit'=>['type'=>'integer','minimum'=>1,'maximum'=>500],'filters'=>['type'=>'object']],'required'=>['source']]],['name'=>'list_reports','description'=>'List authorized saved analyses.','inputSchema'=>$object],['name'=>'get_report','description'=>'Read a saved report and its source snapshot.','inputSchema'=>['type'=>'object','properties'=>['id'=>['type'=>'string']],'required'=>['id']]]];
        if(in_array('content.write',$grant['scopes'],true))$defs[]=['name'=>'save_content','description'=>'Save generated product content to exact product ID or SKU/color. Main and gallery images require existing portal approval. Confirm product and mutation with the user first. Use unique request_id and retain it for retries.','inputSchema'=>['type'=>'object','properties'=>['request_id'=>['type'=>'string'],'product_id'=>['type'=>'string'],'sku'=>['type'=>'string'],'color'=>['type'=>'string'],'kind'=>['type'=>'string','enum'=>['main','gallery','social','size_chart','description']],'url'=>['type'=>'string','description'=>'Public HTTPS direct image download, never sandbox path.'],'base64'=>['type'=>'string'],'openaiFileIdRefs'=>['type'=>'array','items'=>['type'=>'object','properties'=>['id'=>['type'=>'string'],'download_link'=>['type'=>'string']]]],'text'=>['type'=>'string']],'required'=>['request_id','kind']]];
        if(in_array('reports.write',$grant['scopes'],true))$defs[]=['name'=>'save_report','description'=>'Save an analysis linked to authorized source IDs. Confirm with user first.','inputSchema'=>['type'=>'object','properties'=>['request_id'=>['type'=>'string'],'title'=>['type'=>'string'],'text'=>['type'=>'string'],'sources'=>['type'=>'array','items'=>['type'=>'string']]],'required'=>['request_id','title','text','sources']]];
        if(in_array('datasets.write',$grant['scopes'],true))$defs[]=['name'=>'save_dataset','description'=>'Store structured analytical rows, with explicit source and unit, for this project. Never upload secrets. Confirm with user first.','inputSchema'=>['type'=>'object','properties'=>['kind'=>['type'=>'string','enum'=>['custom','advertising','ga4','search_console','branch_inventory']],'name'=>['type'=>'string'],'origin'=>['type'=>'string'],'unit'=>['type'=>'string'],'date_field'=>['type'=>'string'],'rows'=>['type'=>'array','items'=>['type'=>'object']]],'required'=>['kind','name','origin','unit','rows']]];
        $defs[]=['name'=>'social_jobs','description'=>'Read project publishing queue. Queue acceptance is not delivery. Due jobs require an external social tool; never claim publishing happened automatically.','inputSchema'=>$object];
        $defs[]=['name'=>'hub_sales_report','description'=>'Read exact sales report grouped by store/day/month. Choose exactly one authority per store and one currency and grain. Never sum overlapping sources.','inputSchema'=>['type'=>'object','properties'=>['sources'=>['type'=>'array','items'=>['type'=>'string']],'currency'=>['type'=>'string'],'grain'=>['type'=>'string','enum'=>['order','day']],'group'=>['type'=>'string','enum'=>['store','day','month']],'from'=>['type'=>'string'],'to'=>['type'=>'string']],'required'=>['sources','currency','grain','group']]];
        $defs[]=['name'=>'integration_health','description'=>'Read project platform, data authorities and recorded integration health. Configured is not live-tested; no credentials are returned.','inputSchema'=>$object];
        $defs[]=['name'=>'hub_sources','description'=>'List authorized connected WordPress, CRM, Google and imported data sources.','inputSchema'=>$object];
        if(in_array('social.write',$grant['scopes'],true)){
            $defs[]=['name'=>'social_plan','description'=>'After user confirmation write a proposed project calendar, from project sales/SEO/product data. Up to 30 items. Preserves normal calendar approval and does not bypass image approval or publish.','inputSchema'=>['type'=>'object','properties'=>['request_id'=>['type'=>'string'],'items'=>['type'=>'array','items'=>['type'=>'object','properties'=>['platform'=>['type'=>'string'],'kind'=>['type'=>'string'],'scheduled_at'=>['type'=>'integer'],'caption'=>['type'=>'string'],'media'=>['type'=>'array','items'=>['type'=>'string']],'product_id'=>['type'=>'string']],'required'=>['platform','kind','scheduled_at','caption','media']]]],'required'=>['request_id','items']]];
            $defs[]=['name'=>'social_create','description'=>'After user confirmation queue a Telegram post or Instagram post/story/reel/carousel for a Unix timestamp. This does not itself publish.','inputSchema'=>['type'=>'object','properties'=>['request_id'=>['type'=>'string'],'platform'=>['type'=>'string','enum'=>['telegram','instagram']],'kind'=>['type'=>'string','enum'=>['post','story','reel','carousel']],'caption'=>['type'=>'string'],'media'=>['type'=>'array','items'=>['type'=>'string']],'scheduled_at'=>['type'=>'integer'],'product_id'=>['type'=>'string']],'required'=>['request_id','platform','kind','scheduled_at','caption','media']]];
            $defs[]=['name'=>'social_claim','description'=>'Claim a due job exactly once before using your independently connected social publishing app. Expired or uncertain claims must be investigated, never blindly republished.','inputSchema'=>['type'=>'object','properties'=>['id'=>['type'=>'string'],'schedule_externally'=>['type'=>'boolean']],'required'=>['id']]];
            $defs[]=['name'=>'social_ack','description'=>'Record actual external tool outcome and receipt, never a fabricated success. Published receipts are labelled externally reported.','inputSchema'=>['type'=>'object','properties'=>['id'=>['type'=>'string'],'lease'=>['type'=>'string'],'state'=>['type'=>'string','enum'=>['published','scheduled_external','failed','uncertain']],'receipt'=>['type'=>'string']],'required'=>['id','lease','state','receipt']]];
        }
        if(in_array('datasets.write',$grant['scopes'],true))$defs[]=['name'=>'save_hub_records','description'=>'Upsert confirmed source data from connected CRM/Google apps or files into the selected project warehouse. Source ID must already exist. Preserve stable IDs, dates, store, currency and grain.','inputSchema'=>['type'=>'object','properties'=>['source_id'=>['type'=>'string'],'kind'=>['type'=>'string','enum'=>array_keys(AiHub::KINDS)],'batch_id'=>['type'=>'string'],'complete'=>['type'=>'boolean'],'rows'=>['type'=>'array','items'=>['type'=>'object']]],'required'=>['source_id','kind','batch_id','rows']]];
        foreach($defs as &$d){$write=strpos($d['name'],'save_')===0||in_array($d['name'],['social_create','social_claim','social_ack','social_plan'],true);$d['annotations']=['readOnlyHint'=>!$write,'destructiveHint'=>false,'idempotentHint'=>!$write||in_array($d['name'],['save_content','save_report'],true),'openWorldHint'=>false];}unset($d);return $defs;
    }
    public function call($grant,$name,$args){
        if(!is_array($args)||!in_array($name,array_column(self::definitions($grant),'name'),true))throw new RuntimeException('ابزار یا دامنهٔ دسترسی مجاز نیست.');
        if(isset($args['project'])||isset($args['project_id']))throw new RuntimeException('پروژه از اتصال تأییدشده تعیین می‌شود.');
        return AiAccess::run($grant,function($p)use($grant,$name,$args){if(!AiAccess::pageAllowed())throw new RuntimeException('دسترسی اتصال لغو شده است.');AiAccess::scope($grant,'project.read');$data=new AiData($this->store);$content=new AiContent($this->store);
            switch($name){case 'social_plan':return (new AiSocial($this->store))->plan($p,$grant,$args);case 'social_jobs':return (new AiSocial($this->store))->jobs($p);case 'social_create':return (new AiSocial($this->store))->create($p,$grant,$args);case 'social_claim':return (new AiSocial($this->store))->claim($p,$grant,$args['id']??'',!empty($args['schedule_externally']));case 'social_ack':$service=new AiSocial($this->store);$out=$service->ack($p,$grant,$args);$service->reconcile(getCurrentProject($p['id'],true));return $out;case 'integration_health':return (new IntegrationHealth($this->store))->overview($p);case 'hub_sales_report':return (new HubReports($this->store))->sales($p,$args);case 'hub_sources':return (new AiHub($this->store))->sources($p);case 'save_hub_records':AiAccess::scope($grant,'datasets.write');$hub=new AiHub($this->store);return $hub->ingest($p,$hub->source($p,$args['source_id']??''),$args['kind']??'',$args['rows']??null,$args['batch_id']??'',!empty($args['complete']));case 'project_context':return $data->context($p);case 'workflow_counts':return $data->counts($p);case 'read_data':return $data->read($p,$args['source']??'', $args['filters']??[],$args['offset']??0,$args['limit']??100);case 'save_content':return $content->save($grant,$args);case 'save_report':return $content->report($p,$grant,$args);case 'list_reports':return array_map(static fn($r)=>array_intersect_key($r,array_flip(['id','title','origin','at','sources'])),$content->reports($p));case 'get_report':return $content->getReport($p,$args['id']??'');case 'save_dataset':AiAccess::scope($grant,'datasets.write');return ['id'=>$data->putDataset($p,$grant,$args)];}throw new RuntimeException('ابزار یافت نشد.');});
    }
    public static function bearer(){ $header=$_SERVER['HTTP_AUTHORIZATION']??$_SERVER['REDIRECT_HTTP_AUTHORIZATION']??'';if(!preg_match('/^Bearer ([a-f0-9]{64})$/D',$header,$m))throw new RuntimeException('invalid_token');return $m[1];}
    public static function jsonBody($max=12582912){$size=(int)($_SERVER['CONTENT_LENGTH']??0);if($size>$max)throw new RuntimeException('request_too_large');$raw=file_get_contents('php://input',false,null,0,$max+1);if(strlen($raw)>$max)throw new RuntimeException('request_too_large');$d=json_decode($raw,true);if(!is_array($d))throw new RuntimeException('invalid_json');return $d;}
    public static function respond($data,$status=200){http_response_code($status);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');echo json_encode($data,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_INVALID_UTF8_SUBSTITUTE);exit;}
}
